 ICON.cmSyn=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CM_T(0,40,'received',{fs:22,fw:700,fill:CM_MUT})}${CM_bits(0,54,'1010010',{w:60,h:56,hi:{3:ORG}})}${CM_arrow(208,122,208,170,GRN,3)}${CM_T(226,156,'s = 111 = column 4',{fs:24,fw:800,fill:GRN})}${CM_bits(0,182,'1011010',{w:60,h:56,hi:{3:GRN}})}${CM_T(210,280,'codeword restored',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
